        .continue-btn:active {
            transform: translateY(-1px) scale(0.99);
            transition: all 0.15s ease;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1 class="logo">TiffySearch</h1>
            <p class="subtitle">The part of project TiffyTime!</p>
        </div>

        <div class="results-container" id="resultsContainer">
            <div class="powered-by">
                Powered by <span>TiffySearch AI</span> - The part of project TiffyTime!
            </div>
        </div>

        <div class="search-container fixed-bottom" id="searchContainer">
            <div style="display: flex; align-items: center; width: 100%; position: relative;">
                <button class="plus-menu-btn" id="plusMenuBtn">
                    <i class="fas fa-plus"></i>
                </button>
                <div class="search-bar" style="flex: 1;">
                    <input 
                        type="text" 
                        id="searchInput" 
                        placeholder=""
                        autocomplete="off"
                    >
                    <i class="fas fa-search search-icon" id="sendBtn"></i>
                </div>

                <!-- Simple Dropdown Menu -->
                <div class="dropdown-menu" id="dropdownMenu">
                    <div class="menu-item" onclick="openImageGenerator()">
                        <i class="fas fa-image"></i>
                        <span>Képgenerálás</span>
                    </div>
                    <div class="menu-item" onclick="openChatAI()">
                        <i class="fas fa-comments"></i>
                        <span>AI Chat</span>
                    </div>
                    <div class="menu-item" onclick="openAdvancedSearch()">
                        <i class="fas fa-search-plus"></i>
                        <span>Haladó Keresés</span>
                    </div>
                    <div class="menu-item" onclick="openSettings()">
                        <i class="fas fa-cog"></i>
                        <span>Beállítások</span>
                    </div>
                    <div class="menu-item" onclick="window.open('', '_blank')" style="border-top: 1px solid rgba(30, 144, 255, 0.2); font-size: 0.8rem; color: #64748b;">
                        <i class="fas fa-code"></i>
                        <span>build&designed&secured by Sándor Kollár</span>
                    </div>
                </div>
            </div>
        </div></div>

        <!-- Detailed Summary Modal -->
        <div class="detailed-summary-overlay" id="detailedSummaryOverlay" style="display: none;">
            <div class="detailed-summary-container">
                <div class="detailed-summary-content" id="detailedSummaryContent">
                    <!-- Content will be populated by JavaScript -->
                </div>
                <div class="continue-button-container">
                    <button class="continue-btn" id="continueBtn">
                        <i class="fas fa-arrow-left"></i> Folytatás
                    </button>
                </div>
            </div>
        </div>
    </div>

    <script>
        const searchInput = document.getElementById('searchInput');
        const sendBtn = document.getElementById('sendBtn');
        const resultsContainer = document.getElementById('resultsContainer');

        let isLoading = false;
        let currentSearchData = null;
        let currentQuery = '';

        function showLoading() {
            isLoading = true;
            resultsContainer.innerHTML = `
                <div class="loading">
                    <i class="fas fa-spinner"></i>
                    TiffySearch AI gondolkodik...
                </div>
            `;
        }

        function showError(message) {
            const errorDiv = document.createElement('div');
            errorDiv.className = 'error';
            errorDiv.innerHTML = `<i class="fas fa-exclamation-triangle"></i> ${message}`;
            resultsContainer.insertBefore(errorDiv, resultsContainer.firstChild);
        }

        function displayResults(data) {
            if (!data.success) {
                showError(data.error || 'Hiba történt a keresés során');
                return;
            }

            currentSearchData = data;
            currentQuery = data.query;
            resultsContainer.innerHTML = '';

            // AI Answer
            if (data.answer) {
                const aiAnswerDiv = document.createElement('div');
                aiAnswerDiv.className = 'ai-answer';
                aiAnswerDiv.innerHTML = `
                    <h3><i class="fas fa-robot"></i> TiffySearch AI válasza</h3>
                    <p>${data.answer}</p>
                `;
                resultsContainer.appendChild(aiAnswerDiv);
            }

            // More Info Button
            const moreInfoBtn = document.createElement('button');
            moreInfoBtn.className = 'more-info-btn';
            moreInfoBtn.innerHTML = '<i class="fas fa-magic"></i> Részletes elemzés';
            moreInfoBtn.addEventListener('click', showDetailedSummary);
            resultsContainer.appendChild(moreInfoBtn);

            // Sources
            if (data.sources && data.sources.length > 0) {
                const sourcesDiv = document.createElement('div');
                sourcesDiv.className = 'sources';
                sourcesDiv.innerHTML = '<h4><i class="fas fa-link"></i> Források</h4>';

                data.sources.forEach(source => {
                    const sourceItem = document.createElement('div');
                    sourceItem.className = 'source-item';
                    sourceItem.innerHTML = `
                        ${source.title}
                        <div class="source-domain">${source.domain}</div>
                    `;
                    sourcesDiv.appendChild(sourceItem);
                });

                resultsContainer.appendChild(sourcesDiv);
            }

            // Powered by footer
            const poweredBy = document.createElement('div');
            poweredBy.className = 'powered-by';
            poweredBy.innerHTML = 'Powered by <span>TiffySearch AI</span> - The part of project TiffyTime!';
            resultsContainer.appendChild(poweredBy);
        }

        async function showDetailedSummary() {
            if (!currentSearchData || !currentQuery) return;

            // Hide main elements with animation
            const header = document.querySelector('.header');
            const searchContainer = document.getElementById('searchContainer');

            header.classList.add('hidden');
            searchContainer.classList.add('hidden');

            // Show detailed summary overlay
            const overlay = document.getElementById('detailedSummaryOverlay');
            const content = document.getElementById('detailedSummaryContent');

            overlay.style.display = 'block';
            content.innerHTML = `
                <div class="loading">
                    <i class="fas fa-spinner"></i>
                    TiffySearch AI készíti a részletes összefoglalót...
                </div>
            `;

            try {
                const response = await fetch('/detailed_summary', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({ 
                        query: currentQuery,
                        original_data: currentSearchData 
                    })
                });

                const data = await response.json();

                if (data.success) {
                    content.innerHTML = `
                        <h2><i class="fas fa-file-alt"></i> Részletes összefoglaló</h2>
                        <div>${data.detailed_summary}</div>
                    `;
                } else {
                    content.innerHTML = `
                        <div class="error">
                            <i class="fas fa-exclamation-triangle"></i> 
                            Hiba történt a részletes összefoglaló készítése során: ${data.error}
                        </div>
                    `;
                }
            } catch (error) {
                content.innerHTML = `
                    <div class="error">
                        <i class="fas fa-exclamation-triangle"></i> 
                        Hálózati hiba történt. Kérlek próbáld újra!
                    </div>
                `;
            }
        }

        function hideDetailedSummary() {
            const overlay = document.getElementById('detailedSummaryOverlay');
            const header = document.querySelector('.header');
            const searchContainer = document.getElementById('searchContainer');

            // Add slide out animation
            overlay.style.animation = 'slideOut 0.5s ease-out';

            setTimeout(() => {
                overlay.style.display = 'none';
                overlay.style.animation = '';

                // Show main elements
                header.classList.remove('hidden');
                searchContainer.classList.remove('hidden');
            }, 500);
        }

        async function performSearch() {
            const query = searchInput.value.trim();
            if (!query || isLoading) return;

            // Címsor eltüntetése az első keresés után
            const header = document.querySelector('.header');
            if (!header.classList.contains('hidden')) {
                header.classList.add('hidden');
            }

            showLoading();

            try {
                // Képgenerálás kulcsszavak felismerése
                const imageKeywords = [
                    'generálj', 'készíts', 'rajzolj', 'alkoss', 'csinálj',
                    'kép', 'képet', 'image', 'picture', 'photo', 'fotó',
                    'illusztráció', 'ábra', 'drawing', 'artwork', 'art',
                    'festmény', 'portré', 'landscape', 'tájkép'
                ];

                const isImageGeneration = imageKeywords.some(keyword => 
                    query.toLowerCase().includes(keyword.toLowerCase())
                );

                if (isImageGeneration) {
                    await performImageGeneration(query);
                } else {
                    const response = await fetch('/ai_search', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify({ query: query })
                    });

                    const data = await response.json();
                    displayResults(data);
                }
            } catch (error) {
                console.error('Search error:', error);
                showError('Hálózati hiba történt. Kérlek próbáld újra!');
            } finally {
                isLoading = false;
            }
        }

        async function performImageGeneration(query) {
            try {
                // AI segítségével javítjuk a prompt-ot
                const improvedPrompt = await improveImagePrompt(query);

                // Párhuzamosan generálunk képeket mindkét modellel
                const response = await fetch('/generate_combined', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({ 
                        prompt: improvedPrompt,
                        aspect_ratio: '1:1'
                    })
                });

                const data = await response.json();
                displayImageResults(data, query);
            } catch (error) {
                console.error('Image generation error:', error);
                showError('Képgenerálási hiba történt. Kérlek próbáld újra!');
            }
        }

        async function improveImagePrompt(originalQuery) {
            // Egyszerű prompt javítás - eltávolítjuk a "generálj", "készíts" szavakat
            let improvedPrompt = originalQuery
                .replace(/generálj|készíts|rajzolj|alkoss|csinálj/gi, '')
                .replace(/képet|képet|image|picture/gi, '')
                .trim();

            // Ha túl rövid, hozzáadunk részleteket
            if (improvedPrompt.length < 10) {
                improvedPrompt = originalQuery;
            }

            return improvedPrompt;
        }

        function displayImageResults(data, originalQuery) {
            if (!data.success) {
                showError(data.error || 'Hiba történt a képgenerálás során');
                return;
            }

            resultsContainer.innerHTML = '';

            // AI válasz a képgenerálásról
            const aiAnswerDiv = document.createElement('div');
            aiAnswerDiv.className = 'ai-answer';
            aiAnswerDiv.innerHTML = `
                <h3><i class="fas fa-magic"></i> TiffySearch AI Képgenerátor</h3>
                <p>Képeket generáltam a kérésedre: "<strong>${originalQuery}</strong>"</p>
                <p>Az alábbi képeket AI modellek készítették speciálisan a te prompt-od alapján.</p>
            `;
            resultsContainer.appendChild(aiAnswerDiv);

            // Képek megjelenítése
            const imagesContainer = document.createElement('div');
            imagesContainer.style.display = 'grid';
            imagesContainer.style.gridTemplateColumns = 'repeat(auto-fit, minmax(300px, 1fr))';
            imagesContainer.style.gap = '2rem';
            imagesContainer.style.marginBottom = '2rem';

            data.results.forEach((result, index) => {
                const imageCard = document.createElement('div');
                imageCard.className = 'source-item';
                imageCard.style.padding = '1.5rem';
                imageCard.style.textAlign = 'center';

                if (result.success) {
                    imageCard.innerHTML = `
                        <h4 style="color: #1e90ff; margin-bottom: 1rem; font-weight: 600;">
                            <i class="fas fa-image"></i> ${result.model}
                        </h4>
                        <div style="position: relative; margin-bottom: 1rem;">
                            <img src="${result.image_url}" 
                                 alt="Generált kép ${index + 1}" 
                                 style="width: 100%; border-radius: 12px; box-shadow: 0 8px 25px rgba(30, 144, 255, 0.3);"
                                 loading="lazy">
                        </div>
                        <div style="display: flex; gap: 0.5rem; justify-content: center; flex-wrap: wrap;">

                                <i class="fas fa-external-link-alt"></i> Megnyitás


                                <i class="fas fa-download"></i> Letöltés

                        </div>
                    `;
                } else {
                    imageCard.innerHTML = `
                        <h4 style="color: #ff6b6b; margin-bottom: 1rem;">
                            <i class="fas fa-exclamation-triangle"></i> ${result.model} - Hiba
                        </h4>
                        <p style="color: #fca5a5; font-size: 0.9rem;">${result.error}</p>
                    `;
                }

                imagesContainer.appendChild(imageCard);
            });

            resultsContainer.appendChild(imagesContainer);

            // Prompt információ
            const promptInfo = document.createElement('div');
            promptInfo.className = 'sources';
            promptInfo.innerHTML = `
                <h4><i class="fas fa-info-circle"></i> Prompt információ</h4>
                <div class="source-item">
                    <strong>Eredeti kérés:</strong> ${originalQuery}<br>
                    <strong>Optimalizált prompt:</strong> ${data.prompt}<br>
                    <strong>Képarány:</strong> 1:1 (négyzet)<br>
                    <strong>Generálás ideje:</strong> ${new Date().toLocaleTimeString('hu-HU')}
                </div>
            `;
            resultsContainer.appendChild(promptInfo);

            // Powered by footer
            const poweredBy = document.createElement('div');
            poweredBy.className = 'powered-by';
            poweredBy.innerHTML = 'Powered by <span>TiffySearch AI</span> - Google Imagen 4 Ultra & Flux 1.1 Pro Ultra';
            resultsContainer.appendChild(poweredBy);
        }

        // Event listeners
        sendBtn.addEventListener('click', performSearch);

        searchInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                performSearch();
            }
        });

        document.getElementById('continueBtn').addEventListener('click', hideDetailedSummary);

        // Focus on search input
        searchInput.focus();

        // Simple dropdown menu functionality
        const plusMenuBtn = document.getElementById('plusMenuBtn');
        const dropdownMenu = document.getElementById('dropdownMenu');

        plusMenuBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            dropdownMenu.classList.toggle('show');
        });

        // Close menu when clicking outside
        document.addEventListener('click', (e) => {
            if (!plusMenuBtn.contains(e.target) && !dropdownMenu.contains(e.target)) {
                dropdownMenu.classList.remove('show');
            }
        });

        // Menu item functions
        function openImageGenerator() {
            dropdownMenu.classList.remove('show');
            // Automatikusan kitöltjük a keresősávot képgenerálási példával
            searchInput.value = 'Generálj egy gyönyörű tájképet hegekkel és tóval';
            searchInput.focus();
            // Villogtatjuk a keresősávot, hogy felhívjuk a figyelmet
            searchInput.style.background = 'linear-gradient(90deg, rgba(30, 144, 255, 0.2), rgba(0, 191, 255, 0.2))';
            setTimeout(() => {
                searchInput.style.background = '';
            }, 1000);
        }

        function openChatAI() {
            dropdownMenu.classList.remove('show');
            alert('AI Chat funkcionalitás hamarosan elérhető!');
        }

        function openAdvancedSearch() {
            dropdownMenu.classList.remove('show');
            alert('Haladó keresés funkcionalitás hamarosan elérhető!');
        }

        function openSettings() {
            dropdownMenu.classList.remove('show');
            alert('Beállítások funkcionalitás hamarosan elérhető!');
        }
    </script>
</body>
</html>
